final class RateLimitedHttpSender {
    private static final int REQUESTS_PER_SECOND = 5;

    private PoolingHttpClientConnectionManager connManager;

    public RateLimitedHttpSender() {
        // Expanded connection pool sizes to handle the larger volume safely
        connManager = new PoolingHttpClientConnectionManager();
        connManager.setMaxTotal(100);
        connManager.setDefaultMaxPerRoute(50);
    }

    public void sendRequests(List<String> requests) {
        // 2. Build the Apache HttpClient instance
        try (CloseableHttpClient httpClient = HttpClients.custom()
                .setConnectionManager(connManager)
                .build()) {
         // 10 threads might choke on 4900 items if responses are slow. Let's scale to 25.
            ExecutorService requestWorkerPool = Executors.newFixedThreadPool(25);
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

            AtomicInteger dispatchPointer = new AtomicInteger(0);
            // NEW: Track completed responses (both successes and failures)
            AtomicInteger completedCounter = new AtomicInteger(0);
            System.out.println("Starting execution: 5 requests per second...");

            scheduler.scheduleAtFixedRate(() -> {
                for (int i = 0; i < REQUESTS_PER_SECOND; i++) {
                    int currentIndex = dispatchPointer.getAndIncrement();

                    if (currentIndex >= requests.size()) {
                        return;
                    }

                    String url = requests.get(currentIndex);

                    requestWorkerPool.submit(() -> {
                        // Pass the completedCounter to track actual I/O resolution
                        executeHttpRequest(httpClient, url, currentIndex + 1, completedCounter);
                    });
                }
            }, 0, 1, TimeUnit.SECONDS);

            // FIXED: Block the main thread until ALL responses are fully processed, not just dispatched
            while (completedCounter.get() < requests.size()) {
                Thread.sleep(1000);
                System.out.printf("[Progress] Dispatched: %d/%d | Completed: %d/%d%n",
                        Math.min(dispatchPointer.get(),  requests.size()),  requests.size(),
                        completedCounter.get(),  requests.size());
            }

            // Clean shutdown sequence
            scheduler.shutdown();
            scheduler.awaitTermination(5, TimeUnit.SECONDS);
            requestWorkerPool.shutdown();
            requestWorkerPool.awaitTermination(30, TimeUnit.SECONDS);

            System.out.println("\nAll 4900 requests fully completed and logged.");

        } catch (IOException e) {
            e.printStackTrace();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

        private static void executeHttpRequest(CloseableHttpClient httpClient, String url, int requestNum, AtomicInteger completedCounter) {
            HttpGet request = new HttpGet(url);
            try {
                httpClient.execute(request, response -> {
                    int statusCode = response.getCode();
                    EntityUtils.consume(response.getEntity());
                    System.out.printf("[Req #%d] Status: %d | URL: %s%n", requestNum, statusCode, url);
                    return null;
                });
            } catch (IOException e) {
                System.err.printf("Request #%d failed: %s%n", requestNum, e.getMessage());
            } finally {
                // ALWAYS increment this so the main thread accurately counts network completion
                completedCounter.incrementAndGet();
            }
        }
}